export function settle(s,orderId,event){const o=s.orders.find(x=>x.id===orderId);must(o,'Order not found.',404);must(event.currency===o.currency&&event.amountPaise===o.amountPaise&&event.status==='paid','Gateway payment does not match the order.',400);if(o.status==='Paid')return {duplicate:true};must(['Pending','Expired','Cancelled','Failed'].includes(o.status),'Order is closed.',409);const u=s.users.find(u=>u.id===o.user);must(u,'Account not found.',404);const timely=o.status==='Pending'&&Date.parse(o.expiresAt)>Date.now();
 if(o.kind==='membership'){if(!identityEligible(u)||!timely){o.status='Review Required';o.providerRef=event.providerRef;notice(s,u.id,'Payment needs review','Eligibility or checkout expiry changed. Contact support for reconciliation.',o.id);return {review:true}}u.membership={status:'Active',startsAt:now(),expiresAt:new Date(Date.now()+o.plan.days*86400000).toISOString(),plan:copy(o.plan),order:o.id,autoRenew:false};notice(s,u.id,'Membership active',`Access valid until ${u.membership.expiresAt.slice(0,10)}.`,o.id)}
 if(o.kind==='booking'){const b=s.bookings.find(x=>x.id===o.booking);if(!timely||!customerEligible(u)||!companionVisible(getUser(s,b.companion))||b.status!=='Payment Pending'||Date.parse(b.start)<=Date.now()||conflicts(s,b.companion,b.start,b.hours,b.id)){o.status='Review Required';o.providerRef=event.providerRef;notice(s,u.id,'Payment needs review','The booking could not be confirmed. Contact support for reconciliation.',o.id);return {review:true}}b.status='Confirmed';b.paymentStatus='Paid';b.confirmedAt=now();b.paymentRef=event.providerRef;notice(s,b.customer,'Booking confirmed',b.reference,b.id);notice(s,b.companion,'Booking confirmed',b.reference,b.id)}
 if(o.kind==='extension'){const x=s.extensions.find(x=>x.id===o.extension),b=s.bookings.find(x=>x.id===o.booking);if(!timely||!customerEligible(u)||!companionVisible(getUser(s,b.companion))||x.status!=='Payment Pending'||!['Confirmed','In Progress'].includes(b.status)||conflicts(s,b.companion,b.start,b.hours+x.hours,b.id)){o.status='Review Required';o.providerRef=event.providerRef;notice(s,u.id,'Extension payment needs review','Contact support for reconciliation.',o.id);return {review:true}}x.status='Confirmed';b.hours+=x.hours;b.extensions ||= [];b.extensions.push({id:x.id,hours:x.hours,customerPaise:x.customerPaise,paymentRef:event.providerRef,at:now()});notice(s,b.companion,'Booking extended',`${x.hours} extra hours confirmed.`,b.id)}
 o.status='Paid';o.paidAt=now();o.providerRef=event.providerRef;record(s,{id:'payment-gateway'},'Gateway payment confirmed',o.id);return {paid:true}
}
export function maintain(s){for(const u of s.users){if(u.role==='customer'&&u.membership?.status==='Active'){const remaining=Date.parse(u.membership.expiresAt)-Date.now();if(remaining<=0){u.membership.status='Expired';notice(s,u.id,'Membership expired','Renew to restore profile access.')}else if(remaining<3*86400000&&!u.membership.reminded){u.membership.reminded=true;notice(s,u.id,'Membership renewal reminder','Your membership expires within three days. Renewal is manual.')}}}
 s.connections.forEach(c=>{if(['Pending','Change Requested'].includes(c.status)&&Date.parse(c.expiresAt)<=Date.now()){c.status='Expired';notice(s,c.customer,'Connection expired','Send a new request if you would still like to connect.',c.id)}});
 s.bookings.forEach(b=>{if(b.status==='Payment Pending'&&Date.parse(b.holdUntil)<=Date.now()){b.status='Cancelled';b.reason='Payment hold expired.';notice(s,b.customer,'Booking hold expired','Request a new booking.',b.id)}});
 s.orders.forEach(o=>{if(o.status==='Pending'&&Date.parse(o.expiresAt)<=Date.now()){o.status='Expired';if(o.kind==='membership'){const u=s.users.find(u=>u.id===o.user);if(u?.membership?.order===o.id)u.membership=null}}});
 s.extensions.forEach(x=>{if(x.status==='Payment Pending'&&Date.parse(x.holdUntil)<=Date.now())x.status='Expired'});
 s.calls.forEach(c=>{const connection=s.connections.find(x=>x.id===c.connection),customer=s.users.find(u=>u.id===connection?.customer),companion=s.users.find(u=>u.id===connection?.companion);if(['Ringing','Accepted'].includes(c.status)&&(!customerEligible(customer)||(!identityEligible(companion)||['Rejected','Suspended'].includes(companion.profileStatus))||connection?.status!=='Accepted')){c.status='Ended';c.endedAt=now();c.signals=[]}if(c.status==='Ringing'&&Date.parse(c.at)+60000<=Date.now())c.status='Missed';if(c.status==='Accepted'&&Date.parse(c.acceptedAt)+30*60000<=Date.now()){c.status='Ended';c.endedAt=now()}});
}
