export function settleRefund(s,orderId,event){const o=s.orders.find(o=>o.id===orderId),refund=o?.refunds?.find(r=>r.id===event.refundReference);must(o&&refund,'Refund request not found.',404);must(event.amountPaise===refund.amountPaise&&event.currency===o.currency&&event.status==='refunded','Gateway refund does not match the request.');if(refund.status==='Confirmed')return {duplicate:true};refund.status='Confirmed';refund.providerRef=event.providerRef;refund.confirmedAt=now();const sum=o.refunds.filter(r=>r.status==='Confirmed').reduce((n,r)=>n+r.amountPaise,0);if(sum===o.amountPaise){o.status='Refunded';if(o.kind==='membership'){const u=s.users.find(u=>u.id===o.user);if(u.membership?.order===o.id)u.membership.status='Cancelled'}if(o.kind==='booking'){const b=s.bookings.find(b=>b.id===o.booking);b.paymentStatus='Refunded';if(['Payment Pending','Confirmed'].includes(b.status))b.status='Cancelled'}}notice(s,o.user,'Refund confirmed',`${refund.amountPaise/100} INR refunded by the gateway.`,o.id);record(s,{id:'payment-gateway'},'Gateway refund confirmed',o.id,refund.reason);return {refunded:true}}
export function gatewayFailure(s,orderId,event){const o=s.orders.find(o=>o.id===orderId);must(o&&event.amountPaise===o.amountPaise&&event.currency===o.currency&&event.status==='failed','Gateway failure does not match the order.');if(o.status==='Paid'||o.status==='Refunded')return {ignored:true};if(o.status==='Failed')return {duplicate:true};o.status='Failed';o.providerRef=event.providerRef;const u=s.users.find(u=>u.id===o.user);if(o.kind==='membership'&&u.membership?.order===o.id)u.membership=null;if(o.kind==='booking'){const b=s.bookings.find(b=>b.id===o.booking);if(b.status==='Payment Pending'){b.status='Cancelled';b.reason='Payment failed at the gateway.'}}if(o.kind==='extension'){const x=s.extensions.find(x=>x.id===o.extension);x.status='Declined'}notice(s,o.user,'Payment failed','The gateway did not confirm payment. Review your status before retrying.',o.id);record(s,{id:'payment-gateway'},'Gateway payment failed',o.id);return {failed:true}}
